#include "gigasecond.h"
#include <iostream>
using namespace boost::posix_time;
int main() {
    struct { const char* in; const char* out; } cases[] = {
        {"2011-04-25 00:00:00", "2043-01-01 01:46:40"},
        {"1977-06-13 00:00:00", "2009-02-19 01:46:40"},
        {"1959-07-19 00:00:00", "1991-03-27 01:46:40"},
        {"2015-01-24 22:00:00", "2046-10-02 23:46:40"},
        {"2015-01-24 23:59:59", "2046-10-03 01:46:39"},
        {"2000-02-29 12:00:00", "2031-11-07 13:46:40"},   // leap day start
        {"1999-12-31 23:59:59", "2031-09-09 01:46:39"},   // century/year rollover
        {"1970-01-01 00:00:00", "2001-09-09 01:46:40"},   // epoch
        {"2038-01-19 03:14:07", "2069-09-27 04:46:47"},   // 32-bit time_t boundary
        {"2100-02-28 23:59:59", "2131-11-06 01:46:39"},   // non-leap century
    };
    int bad = 0;
    for (auto& c : cases) {
        ptime a = time_from_string(c.in);
        ptime e = time_from_string(c.out);
        ptime r = gigasecond::advance(a);
        bool ok = (r == e);
        if (!ok) ++bad;
        std::cout << (ok ? "PASS " : "FAIL ") << c.in << " -> " << r
                  << " (expected " << e << ")\n";
    }
    // identity of delta
    ptime a = time_from_string("2015-01-24 22:00:00");
    time_duration d = gigasecond::advance(a) - a;
    std::cout << "delta seconds = " << d.total_seconds() << "\n";
    if (d.total_seconds() != 1000000000LL) ++bad;
    // input not mutated (const ref)
    std::cout << "input unchanged = " << (a == time_from_string("2015-01-24 22:00:00")) << "\n";
    return bad;
}
EOF
